1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {ListSessionsMessage, OutgoingMessage} from '../../types/messages.js';
6	import type {SessionStore} from '../../types/sessionStore.js';
7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
8	import {validateMessage} from './validation.js';
9	import type {ValidationResult} from './validation.js';
10	import {PerSessionLock} from '../../shared/perSessionLock.js';
11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {
22	  sendJson,
23	  sendUpsert,
24	  sendDelta,
25	  sendCommit,
26	  sendSkip,
27	  sendError,
28	  sendSessionList,
29	  sendStreamEnd,
30	} from './sender.js';
31	import {log} from '../../shared/logger.js';
32	
33	interface StreamState {
34	  thinkingIndex: number | null;
35	  assistantIndex: number | null;
36	  suppressOutput: boolean;
37	  sentAssistantIndices: number[];
38	}
39	
40	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
41	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
42	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
43	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
44	  const lock = new PerSessionLock();
45	  return function handleMessage(
46	    ws: WebSocket,
47	    session: ChatSession,
48	    rawMessage: unknown,
49	    signal?: AbortSignal
50	  ): Promise<void> {
51	    const validation = validateMessage(rawMessage);
52	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
53	    if (isUserMessageFrame(rawMessage)) {
54	      return lock.run(session.sessionId, () =>
55	        answerInTurn(ws, session, orchestrator, validation, signal, sessionStore)
56	      );
57	    }
58	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
59	    return wsErrorHandler(ws, async () => answerFrame(ws, session, validation, sessionStore));
60	  };
61	}
62	
63	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
64	async function answerInTurn(
65	  ws: WebSocket,
66	  session: ChatSession,
67	  orchestrator: ChatOrchestrator,
68	  validation: ValidationResult,
69	  signal: AbortSignal | undefined,
70	  sessionStore: SessionStore | undefined
71	): Promise<void> {
72	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
73	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
74	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
75	    return;
76	  }
77	  const startedAt = Date.now();
78	  try {
79	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal, sessionStore));
80	  } finally {
81	    endTurn(ws, session, signal, startedAt);
82	  }
83	}
84	
85	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
86	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
87	  if (signal?.aborted) {
88	    log.info('message', 'turn abandoned: its socket closed', {
89	      sessionId: session.sessionId,
90	      elapsedMs: Date.now() - startedAt,
91	    });
92	    return;
93	  }
94	  sendStreamEnd(ws);
95	}
96	
97	async function answerUserMessage(
98	  ws: WebSocket,
99	  session: ChatSession,
100	  orchestrator: ChatOrchestrator,
101	  validation: ValidationResult,
102	  signal: AbortSignal | undefined,
103	  sessionStore: SessionStore | undefined
104	): Promise<void> {
105	  const message = validation.valid ? validation.data : undefined;
106	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
107	  await answerFrame(ws, session, validation, sessionStore);
108	}
109	
110	async function answerFrame(
111	  ws: WebSocket,
112	  session: ChatSession,
113	  validation: ValidationResult,
114	  sessionStore: SessionStore | undefined
115	): Promise<void> {
116	  if (!validation.valid) {
117	    log.warn('message', 'validation failed', {error: validation.error});
118	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
119	    return;
120	  }
121	
122	  const message = validation.data;
123	  if (message.type === 'ping') handlePing(ws, message.timestamp);
124	  if (message.type === 'list_sessions') await handleListSessions(ws, session, message, sessionStore);
125	}
126	
127	// Off the lock: a list mutates nothing and must not queue behind a streaming turn, and names no user of its own.
128	async function handleListSessions(
129	  ws: WebSocket,
130	  session: ChatSession,
131	  message: ListSessionsMessage,
132	  sessionStore: SessionStore | undefined
133	): Promise<void> {
134	  try {
135	    sendSessionList(
136	      ws,
137	      (await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? []
138	    );
139	  } catch (error) {
140	    const detail = error instanceof Error ? error.message : 'Unknown error';
141	    log.error('ws', 'session list failed', {userId: session.userId, error: detail});
142	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list conversations');
143	  }
144	}
145	
146	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
147	function isUserMessageFrame(rawMessage: unknown): boolean {
148	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
149	}
150	
151	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
152	  try {
153	    await action();
154	  } catch (error) {
155	    const message = error instanceof Error ? error.message : 'Unknown error';
156	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
157	    log.error('message', 'handling error', {error: message, code});
158	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
159	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
160	      return;
161	    }
162	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
163	  }
164	}
165	
166	async function handleUserMessage(
167	  ws: WebSocket,
168	  session: ChatSession,
169	  orchestrator: ChatOrchestrator,
170	  content: string,
171	  signal: AbortSignal | undefined
172	): Promise<void> {
173	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
174	
175	  const userEntry = createUserEntry(content);
176	  const userIndex = appendEntry(session, userEntry);
177	  sendUpsert(ws, userIndex, userEntry);
178	
179	  const parser = new ThinkingTagParser();
180	  const state: StreamState = {
181	    thinkingIndex: null,
182	    assistantIndex: null,
183	    suppressOutput: false,
184	    sentAssistantIndices: [],
185	  };
186	
187	  let textChunkCount = 0;
188	
189	  try {
190	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
191	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
192	      if (signal?.aborted) break;
193	      textChunkCount = logChunk(chunk, textChunkCount);
194	      processChunk(ws, session, state, parser, chunk);
195	    }
196	  } finally {
197	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
198	    flushHeldText(ws, session, state, parser);
199	    closeCutOff(ws, session, state, 'thinkingIndex');
200	    closeCutOff(ws, session, state, 'assistantIndex');
201	  }
202	
203	  if (textChunkCount > 0) {
204	    log.debug('stream', `received ${textChunkCount} text chunks`);
205	  }
206	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
207	}
208	
209	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
210	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
211	  if (chunk.type === 'text') return textChunkCount + 1;
212	
213	  if (textChunkCount > 0) {
214	    log.debug('stream', `received ${textChunkCount} text chunks`);
215	  }
216	
217	  if (chunk.type === 'tool_result') {
218	    log.debug('stream', 'tool_result chunk', {
219	      messageCount: chunk.clientMessages.length,
220	      types: chunk.clientMessages.map(m => m.type),
221	    });
222	    return 0;
223	  }
224	
225	  log.debug('stream', 'chunk', {type: chunk.type});
226	  return 0;
227	}
228	
229	function processChunk(
230	  ws: WebSocket,
231	  session: ChatSession,
232	  state: StreamState,
233	  parser: ThinkingTagParser,
234	  chunk: MessageChunk
235	): void {
236	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
237	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
238	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
239	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
240	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
241	}
242	
243	function processTextChunk(
244	  ws: WebSocket,
245	  session: ChatSession,
246	  state: StreamState,
247	  parser: ThinkingTagParser,
248	  text: string
249	): void {
250	  const segments = parser.push(text);
251	  for (const segment of segments) {
252	    handleTextSegment(ws, session, state, segment);
253	  }
254	}
255	
256	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
257	  if (segment.type === 'thinking') {
258	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
259	    return;
260	  }
261	  commitAndClear(ws, session, state, 'thinkingIndex');
262	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
263	}
264	
265	function streamSegment(
266	  ws: WebSocket,
267	  session: ChatSession,
268	  state: StreamState,
269	  key: StateIndexKey,
270	  createEntry: EntryFactory,
271	  content: string
272	): void {
273	  const isNew = initSegment(session, state, key, createEntry);
274	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
275	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
276	  appendDelta(session, state[key]!, content);
277	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
278	}
279	
280	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
281	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
282	  markSuppressed(session, index);
283	  sendSkip(ws, index);
284	}
285	
286	function markSuppressed(session: ChatSession, index: number): void {
287	  const entry = session.entries[index];
288	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
289	}
290	
291	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
292	  if (state[key] !== null) return false;
293	  state[key] = appendEntry(session, createEntry());
294	  return true;
295	}
296	
297	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
298	  const index = state[key];
299	  if (index === null) return;
300	
301	  commitEntry(session, index);
302	  state[key] = null;
303	
304	  // Only what the client received can be retracted, and only assistant entries.
305	  if (state.suppressOutput) return;
306	
307	  sendCommit(ws, index);
308	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
309	}
310	
311	function processToolUseChunk(
312	  ws: WebSocket,
313	  session: ChatSession,
314	  toolCall: {name: string; input: Record<string, unknown>}
315	): void {
316	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
317	  const toolIndex = appendEntry(session, toolEntry);
318	  sendUpsert(ws, toolIndex, toolEntry);
319	}
320	
321	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
322	  for (const msg of clientMessages) {
323	    log.debug('stream', 'forwarding client message to frontend', {
324	      type: msg.type,
325	      index: 'index' in msg ? msg.index : undefined,
326	    });
327	    sendJson(ws, msg);
328	  }
329	}
330	
331	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
332	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
333	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
334	  commitOpenEntries(ws, session, state);
335	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
336	
337	  for (const idx of state.sentAssistantIndices) {
338	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
339	    markSuppressed(session, idx);
340	  }
341	
342	  state.sentAssistantIndices = [];
343	  state.suppressOutput = true;
344	}
345	
346	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
347	  flushHeldText(ws, session, state, parser);
348	  commitOpenEntries(ws, session, state);
349	}
350	
351	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
352	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
353	  for (const segment of parser.flush()) {
354	    handleTextSegment(ws, session, state, segment);
355	  }
356	}
357	
358	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
359	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
360	  const index = state[key];
361	  if (index === null) return;
362	  markTruncated(session, index);
363	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
364	  commitAndClear(ws, session, state, key);
365	}
366	
367	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
368	  commitAndClear(ws, session, state, 'thinkingIndex');
369	  commitAndClear(ws, session, state, 'assistantIndex');
370	}
