1	import type {AddressInfo} from 'node:net';
2	import {WebSocket} from 'ws';
3	import type {Express} from 'express';
4	import {createServer} from './createServer.js';
5	import type {HalServer, HalServerOptions} from './createServer.js';
6	import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
7	import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
8	import type {MessageChunk} from '../types/ai.js';
9	import type {ChatSession} from '../types/session.js';
10	import type {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
11	import type {SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
12	
13	// Shared by the suites that need a real upgrade over a real socket, which no double can stand in for.
14	
15	const servers: HalServer[] = [];
16	const clients: WebSocket[] = [];
17	
18	/** An orchestrator that answers once and stops, which is what commits the turn's assistant entry. */
19	export const answeringOrchestrator: ChatOrchestrator = {
20	  processMessage: async () => 'hi',
21	  async *processMessageStream(): AsyncGenerator<MessageChunk> {
22	    yield {type: 'text', text: 'hi'};
23	    yield {type: 'stop', stopReason: 'end_turn'};
24	  },
25	};
26	
27	/** Starts an engine on an ephemeral port and returns the URL a client should open. */
28	export async function startEngine(
29	  sessionStore: SessionStore,
30	  onDisconnect?: (sessionId: string) => void
31	): Promise<string> {
32	  const {url} = await startEngineWith({sessionStore, onDisconnect});
33	  return url;
34	}
35	
36	/** Starts an engine with whatever a suite overrides, returning the server itself beside the URL a client should open. */
37	export async function startEngineWith(
38	  options: Partial<HalServerOptions> & Pick<HalServerOptions, 'sessionStore'>
39	): Promise<{url: string; hal: HalServer}> {
40	  const hal = createServer({
41	    app: (() => undefined) as unknown as Express,
42	    wsAuth: async () => ({id: 'u1'}),
43	    orchestrator: answeringOrchestrator,
44	    ...options,
45	  });
46	  await hal.start(0);
47	  servers.push(hal);
48	  const {port} = hal.server.address() as AddressInfo;
49	  return {url: `ws://127.0.0.1:${port}/hal/ws/c1`, hal};
50	}
51	
52	/** Opens a client that the suite's teardown will close, whether its test passed or failed. */
53	export function connectClient(url: string, token = 't'): WebSocket {
54	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
55	  clients.push(client);
56	  return client;
57	}
58	
59	/** Registers an engine a suite started by hand, so teardown stops it even when its test failed. */
60	export function trackServer(hal: HalServer): HalServer {
61	  servers.push(hal);
62	  return hal;
63	}
64	
65	/** A promise a test settles by hand, to hold a stream or a hook at a point of its choosing. */
66	export function deferred(): {until: Promise<void>; release: () => void} {
67	  let release = (): void => undefined;
68	  const until = new Promise<void>(resolve => {
69	    release = resolve;
70	  });
71	  return {until, release};
72	}
73	
74	/** Resolves with every frame type seen up to and including the first `until` frame. */
75	export function framesUntil(client: WebSocket, until: string): Promise<string[]> {
76	  const seen: string[] = [];
77	  return new Promise<string[]>(resolve => {
78	    client.on('message', raw => {
79	      const {type} = JSON.parse(String(raw)) as {type: string};
80	      seen.push(type);
81	      if (type === until) resolve(seen);
82	    });
83	  });
84	}
85	
86	/** Opens a client that asks one question the moment the socket opens, resolving on the first `until` frame. */
87	export function askOnOpen(
88	  url: string,
89	  {until = 'stream_end', token}: {until?: string; token?: string} = {}
90	): {client: WebSocket; finished: Promise<string[]>} {
91	  const client = connectClient(url, token);
92	  const finished = framesUntil(client, until);
93	  client.on('open', () => client.send(JSON.stringify({type: 'user_message', content: 'hello'})));
94	  return {client, finished};
95	}
96	
97	/** The session id the client's `connected` frame announces, read after the fact; attach it before any frame arrives. */
98	export function announcedId(client: WebSocket): () => string {
99	  let sessionId = '';
100	  client.on('message', raw => {
101	    const frame = JSON.parse(String(raw)) as {type: string; sessionId?: string};
102	    if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
103	  });
104	  return () => sessionId;
105	}
106	
107	/** Tears every socket and server down, each server seeing its sockets close before it stops. */
108	export async function stopEngines(): Promise<void> {
109	  for (const client of clients.splice(0)) client.terminate();
110	  for (const hal of servers.splice(0)) {
111	    const {wss} = hal;
112	    await eventually(() => wss.clients.size === 0);
113	    await hal.stop();
114	  }
115	}
116	
117	/** Polls until a check holds or half a second passes, so a red test reports instead of hanging the run. */
118	export async function eventually(check: () => boolean): Promise<void> {
119	  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
120	}
121	
122	/** The row a list test answers with: a conversation of four entries, last touched at 00:02 on 1 January. */
123	export const storedSummary: SessionSummary = {
124	  sessionId: 's2',
