// Diagnostic only: reproduces the two red acceptance scenarios to see the wire order and the 501.
import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import {createServer} from '../workspace/target/src/transport/createServer.js';
import {InMemorySessionStore} from '../workspace/target/src/infrastructure/stores/inMemorySessionStore.js';
import type {SessionStore} from '../workspace/target/src/types/sessionStore.js';
import {setLogger} from '../workspace/target/src/shared/logger.js';

const logs: string[] = [];
setLogger({
  debug: (c, m, f) => void logs.push(`DEBUG ${c} ${m} ${JSON.stringify(f ?? {})}`),
  info: (c, m, f) => void logs.push(`INFO ${c} ${m} ${JSON.stringify(f ?? {})}`),
  warn: (c, m, f) => void logs.push(`WARN ${c} ${m} ${JSON.stringify(f ?? {})}`),
  error: (c, m, f) => void logs.push(`ERROR ${c} ${m} ${JSON.stringify(f ?? {})}`),
});

const start = async (store: SessionStore): Promise<string> => {
  const hal = createServer({
    app: (() => undefined) as never,
    wsAuth: async () => ({id: 'u1'}),
    sessionStore: store,
    orchestrator: {async *processMessageStream() { yield {type: 'stop', stopReason: 'end_turn'}; }} as never,
  });
  await hal.start(0);
  const {port} = hal.server.address() as AddressInfo;
  return `ws://127.0.0.1:${port}/hal/ws`;
};

const ask = (url: string, outbound: unknown): Promise<{order: string[]}> =>
  new Promise((resolve, reject) => {
    const client = new WebSocket(url, ['hal.ws.v1', 't']);
    const order: string[] = [];
    client.on('error', err => {
      order.push(`client-error: ${String(err)}`);
      resolve({order});
    });
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as {type: string};
      order.push(frame.type);
      if (frame.type === 'connected') {
        client.send(JSON.stringify(outbound));
        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
      }
      if (frame.type === 'pong') {
        // Keep listening a while after the pong, to see what lands after it.
        setTimeout(() => {
          client.terminate();
          resolve({order});
        }, 150);
      }
    });
  });

const inner = new InMemorySessionStore();
const withoutList: SessionStore = {
  create: (a, b, c) => inner.create(a, b, c),
  get: a => inner.get(a),
  delete: a => inner.delete(a),
  count: () => inner.count(),
  clear: () => inner.clear(),
};
const failingList: SessionStore = {
  ...withoutList,
  listFor: () => Promise.reject(new Error('database offline')),
};

console.log('--- scenario A: rejecting listFor, frame order around the pong ---');
{
  const url = await start(failingList);
  for (let i = 0; i < 6; i++) {
    const {order} = await ask(url, {type: 'list_sessions'});
    console.log(`run ${i}:`, order.join(' | '));
  }
  const wss = await start(withoutList);
  console.log('--- scenario B: store with no listFor ---');
  for (let i = 0; i < 3; i++) {
    const {order} = await ask(wss, {type: 'list_sessions'});
    console.log(`run ${i}:`, order.join(' | '));
  }
}

console.log('--- scenario C: nine sequential connections, one server ---');
{
  const url = await start(withoutList);
  for (let i = 0; i < 9; i++) {
    const {order} = await ask(url, {type: 'list_sessions', limit: 'ten'});
    console.log(`run ${i}:`, order.join(' | '));
  }
}

console.log('--- logs (error/warn only) ---');
for (const line of logs) if (!line.startsWith('INFO') && !line.startsWith('DEBUG')) console.log(line);
process.exit(0);

