// Off the lock still means in order: a client that pings after asking must be able to read the answer first.
describe('frames answered in arrival order off the lock', () => {
  it('answers a ping sent after a list_sessions after the list answer, while both still bypass the turn lock', async () => {
    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const gate = deferred();
    const store = {listFor: () => gate.until.then(() => [])} as unknown as Parameters<typeof createMessageHandler>[1];
    const handle = createMessageHandler({} as unknown as ChatOrchestrator, store);

    const list = handle(ws, session, {type: 'list_sessions'});
    await afterPendingWork();
    void handle(ws, session, {type: 'ping', timestamp: 7});
    await afterPendingWork();

    const beforeTheListAnswered = wire(sent);
    gate.release();
    await list;

    expect({beforeTheListAnswered, frames: wire(sent)}).toEqual({
      beforeTheListAnswered: [],
      frames: ['session_list', 'pong 7'],
    });
  });
});

